  "daemon.queued_messages_lost.held": "Bu oturuma iletinin tamamı yazılamadığı için ileti bırakıldı. Oturumun giriş kutusunda iletinin bir bölümü bulunabilir. Bırakılan iletinin arkasındaki kuyrukta bulunan veya şimdi gönderilen iletiler bir istemin gönderilmesini her biri en fazla yaklaşık bir dakika bekler, ardından giriş kutusundakilerle birlikte yazılır. İstem göndermeden önce oturumun giriş kutusunu kontrol edin.",
