  "daemon.trust_directory_too_broad": "{path} yolunun kapsamı, tamamına güvenmek için fazla geniş. Dosya sisteminin kökü ya da ana dizininiz veya bunlardan birini içeren bir konum. Yalnızca bu projeye güvenin veya projeyi daha dar kapsamlı bir klasöre taşıyıp o klasöre güvenin.",
  "daemon.trust_directory_unreachable": "{path} veya üst klasörü zamanında yanıt vermediği için klasör kontrol edilemedi. Yalnızca bu projeye güvenmek için klasör seçeneğinin işaretini kaldırın veya disk bölümü yeniden yanıt verdiğinde tekrar deneyin.",
  "daemon.trust_path_not_absolute": "{path} mutlak bir yol olmadığından güvenilecek üst klasörü yok.",
  "daemon.trust_home_unknown": "Ana dizin belirlenemediğinden hiçbir klasör onunla karşılaştırılamıyor.",
  "daemon.trust_not_waiting": "Bu oturum artık ajanının güven onayında beklemiyor.",
