  "daemon.command_not_recognised": "{agent}, {command} yerine {offered} çalıştıracaktı, bu yüzden komut gönderilmedi. Hâlâ giriş kutusundaysa silin.",
  "daemon.command_not_found": "{agent}, {command} komutunu tanımıyor, bu yüzden komut gönderilmedi. Hâlâ giriş kutusundaysa silin.",
  "daemon.console_session_trust_not_asked": "Uygulama, konsol oturumunun güven onayına sormadan basar.",
