  "settings.startQuotaWindows.label": "Kullanım dönemlerini otomatik başlat",
  "settings.startQuotaWindows.description.off": "Açıldığında kullanım dönemi, sınırı sıfırlanınca saymaya başlar. Bu, hesabın kullanım sınırlarına az miktarda yansır.",
  "settings.startQuotaWindows.requestDescription.off": "Açıldığında kullanım dönemi, sınırı sıfırlanınca saymaya başlar. Bunun için her hesapta küçük bir istek gönderilir; bu, hesabın kullanım sınırlarına az miktarda yansır.",
  "settings.startQuotaWindows.description.on": "Kullanım dönemi, sınırı sıfırlanınca saymaya başlar. Bu, hesabın kullanım sınırlarına az miktarda yansır.",
  "settings.startQuotaWindows.requestDescription.on": "Kullanım dönemi, sınırı sıfırlanınca saymaya başlar. Bunun için her hesapta küçük bir istek gönderilir; bu, hesabın kullanım sınırlarına az miktarda yansır.",
  "settings.startQuotaWindows.help": "Kullanım dönemlerini otomatik başlatma hakkında",
  "settings.startQuotaWindows.helpText": "Sıfırlanmış bir kullanım dönemi, hesabın sonraki isteğine kadar saymaya başlamaz; o zamana kadar geri sayım göstermez ve ne kadar beklerse sonraki sıfırlanması o kadar geç olur. Bu ayar açıkken dönemi başlatmak için o hesapta ajanın en ucuz modeliyle küçük bir istek gönderilir.",
