  "settings.gitWorkflow.development.description.worktree": "Proje oturumundan dosyaları değiştirmeden önce kendi dalını ve çalışma ağacını oluşturması istenir. Değişiklik yalnızca daha sonra başlatılan oturumlara uygulanır; projenin kendi çalışma ağacı ve dal kuralları önceliklidir.",
  "settings.gitWorkflow.squash.label": "Teslimden önce işlemeleri birleştir",
  "settings.gitWorkflow.squash.description.off": "Açıldığında birleştirme, gönderme veya çekme isteği açma öncesinde her özelliğin işlemeleri tek işlemede birleştirilir. İlgisiz hata düzeltmesi kendi işlemesini korur. Değişiklikler yalnızca daha sonra başlatılan oturumlara uygulanır ve proje kuralları önceliklidir.",
  "settings.gitWorkflow.squash.description.on": "Birleştirme, gönderme veya çekme isteği açma öncesinde her özelliğin işlemeleri tek işlemede birleştirilir. İlgisiz hata düzeltmesi kendi işlemesini korur. Değişiklikler yalnızca daha sonra başlatılan oturumlara uygulanır ve proje kuralları önceliklidir.",
  "settings.gitWorkflow.rebaseBeforeDelivery.label": "Teslimden önce yeniden temellendir",
  "settings.gitWorkflow.rebaseBeforeDelivery.description.off": "Açıldığında tamamlanan çalışma birleştirme, gönderme veya çekme isteğiyle teslim edilmeden önce dal hedef dalına yeniden temellendirilir. Değişiklik yalnızca daha sonra başlatılan oturumlara uygulanır ve projenin kendi kuralları önceliklidir.",
  "settings.gitWorkflow.rebaseBeforeDelivery.description.on": "Tamamlanan çalışma birleştirme, gönderme veya çekme isteğiyle teslim edilmeden önce dal hedef dalına yeniden temellendirilir. Değişiklik yalnızca daha sonra başlatılan oturumlara uygulanır ve projenin kendi kuralları önceliklidir.",
  "settings.gitWorkflow.delivery.label": "Teslim",
  "settings.gitWorkflow.delivery.description": "Kimse nasıl teslim edileceğini belirtmediğinde oturumun tamamlanan çalışmayı nasıl teslim edeceği. Değişiklik yalnızca daha sonra başlatılan oturumlara uygulanır ve projenin kendi kuralları önceliklidir.",
  "settings.gitWorkflow.delivery.ask": "Her seferinde sor",
  "settings.gitWorkflow.delivery.merge": "Yerel olarak birleştir",
  "settings.gitWorkflow.delivery.pullRequest": "Çekme isteği aç",
  "settings.gitWorkflow.revertGate.label": "Geri alma koruması",
  "settings.gitWorkflow.revertGate.description.off": "Açıldığında proje oturumunda, hedef dalında zaten bulunan değişiklikleri sessizce geri alan dal güncellemesi engellenir. Değişiklik, çalışan oturumlar dahil hemen geçerli olur.",
  "settings.gitWorkflow.revertGate.description.on": "Proje oturumunda, hedef dalında zaten bulunan değişiklikleri sessizce geri alan dal güncellemesi engellenir. Değişiklik, çalışan oturumlar dahil hemen geçerli olur.",
  "settings.gitWorkflow.revertGate.help": "Geri alma korumasını geçme hakkında",
  "settings.gitWorkflow.revertGate.deliberate": "Genellikle birleştirme veya yeniden temellendirme çakışmalarının yanlış çözülmesinden sonra, hedef daldaki mevcut değişiklikleri sessizce kaldıran güncellemeleri engeller. Bir işlemeyi bilinçli olarak geri almak için {gitRevert} kullanın veya geri alan işlemenin iletisine {reverts} satırı ekleyin; güncelleme korumayı geçer.",
  "settings.gitWorkflow.on": "Açık",
  "settings.gitWorkflow.off": "Kapalı",
  "settings.trusted.description": "Bu klasörlerde, daha sonra eklenenler dahil tüm projelerde tüm ajanların güven onayları size sorulmadan kabul edilir. Her ajan güveni kendi yapılandırmasına kaydeder ve projenin kendi izin kurallarını ve kancalarını uygular. Klasöre bir oturumun güven iletişim kutusundan güvenilir. Bir klasöre yalnızca içine girecek her şeye güveniyorsanız güvenin.",
